// === Tab: mySketch ===
let vs = `
   precision highp float;
   precision highp int;

   attribute vec3 aPosition;
   attribute vec2 aTexCoord;
   varying vec2 vTexCoord;
   uniform mat4 uProjectionMatrix;
   uniform mat4 uModelViewMatrix;

    void main() {
      vec4 positionVec4 = vec4(aPosition, 1.0);
      gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
      vTexCoord = aTexCoord;
   }
`;

let fs = `
   precision highp float;
   precision highp int;

   varying vec2 vTexCoord;

   uniform sampler2D u_tex0;
   uniform sampler2D u_tex1;
   void main() {
      vec2 uv = vTexCoord;

      vec4 color0 = texture2D(u_tex0, uv);
      vec4 color1 = texture2D(u_tex1, uv);

			vec4 color = mix(color0, color1, vTexCoord.x);

      gl_FragColor = vec4(color.rgb, 1.0);
    }
`;

const w = 834;
let theShader ;

function setup() {
   createCanvas(4*w/3, w, WEBGL);

   rectMode(CENTER);
   imageMode(CENTER);
   textureMode(NORMAL);
   colorMode(HSB);
   noStroke();
	 rotate(PI/2);
   theShader = createShader(vs, fs);

   img = []
	 img[0] = set_graphics()
	 img[1] = set_graphics()

   background(100);
   fill(0, 0, 0, 0);

   shader(theShader);
   theShader.setUniform(`u_tex0`, img[0]);
   theShader.setUniform(`u_tex1`, img[1]);

   rect(0, 0, w, w);
}

function set_graphics(){
  let img = createGraphics(w, w);
  img.colorMode(HSB);

  //drawing setting
  const scale_x = 10;
  const scale_y = 10;
  const offset_x = 0;
  const offset_y = 0;

  const pos_range_x = 30;
  const pos_range_y = 30;
  const point_size_max = 10;
  const point_brightness_max = 40;

  //Loop parameter
  const loop_set = 200;
  const loop_point = 300;

  //function parameter
  const b = random(0.5,1) * random([-1,1]);
  const c = random(0.5,1) * random([-1,1]);
  const d = random(0.5,1) * 0.01 * random([-1,1]);

  //point interval   greater is more detail
  const dt = 200;


	img.noStroke();
	img.fill(random(360), 100, 90)
  img.background(100);
  img.translate(w/2, w/2);

  for(let i=0; i<loop_set; i++){
    let x = random(-1,1) * pos_range_x;
    let y = random(-1,1) * pos_range_y;

    for(let j=0; j<loop_point; j++){
      const dx = y;
      const dy = -b*y -c*x -d*y*y*y; //function
      x += dx/dt
      y += dy/dt

      img.push();
      img.translate((x+offset_x)*scale_x, (y+offset_y)*scale_y);
      img.ellipse(0, 0, point_size_max * noise(x/500, y/500, i/20+j/20));
      img.pop();
    }
  }

	return img
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

